package com.example.demo.controller;

import com.example.demo.entity.Product; import com.example.demo.repository.ProductRepository; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController { private final ProductRepository products; public ProductController(ProductRepository products){this.products=products;} @GetMapping public List<Product> all(){return products.findAll();} @GetMapping("/{id}") public Product one(@PathVariable Long id){return products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));} @PostMapping public ResponseEntity<Product> create(@Valid @RequestBody Product p){return ResponseEntity.status(201).body(products.save(p));} @PutMapping("/{id}") public Product update(@PathVariable Long id,@Valid @RequestBody Product p){Product x=one(id);x.setName(p.getName());x.setDescription(p.getDescription());x.setPrice(p.getPrice());x.setStock(p.getStock());return products.save(x);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){products.delete(one(id));return ResponseEntity.noContent().build();} }
